sys_script_include.script:
var BaseValidation = Class.create();
BaseValidation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // Função que o seu Client Script chama via GlideAjax
    validateBaseDuplicity: function() {
        var baseId = this.getParameter('sysparm_base_id');
        var baseName = this.getParameter('sysparm_base_name');
        var baseCity = this.getParameter('sysparm_base_city');
        var baseState = this.getParameter('sysparm_base_state');

        // Proteção: Se o nome vier vazio da tela, nem gasta processamento no banco
        if (!baseName) { return 'ok'; }

        // 1. CHECAGEM DO NOME DA BASE (Prioridade Máxima)
        var grName = new GlideRecord('x_1902784_base_a_0_base_registration');
        grName.addQuery('name', baseName); // Se o campo novo for u_name, mude aqui para 'u_name'
        grName.query();

        while (grName.next()) {
            // Se achar o mesmo nome em OUTRO registro (IDs diferentes), retorna o erro de nome
            if (grName.getUniqueValue() != baseId) {
                return 'duplicate_name';
            }
        }

        // 2. CHECAGEM DE CIDADE + ESTADO COMBINADOS
        if (baseCity && baseState) {
            var grLocation = new GlideRecord('x_1902784_base_a_0_base_registration');
            grLocation.addQuery('city', baseCity);
            grLocation.addQuery('state', baseState);
            grLocation.query();

            while (grLocation.next()) {
                // Se achar a mesma combinação em OUTRO registro, retorna o erro de localidade
                if (grLocation.getUniqueValue() != baseId) {
                    return 'duplicate_location';
                }
            }
        }

        // Se passou por tudo sem retornar erro, tá liberado salvar
        return 'ok';
    },

    type: 'BaseValidation'
});
